from pathlib import Path
import base64,gzip,json

p=Path("index.html")
text=p.read_text(encoding="utf-8")
data=json.loads(gzip.decompress(base64.b64decode("")).decode("utf-8"))
css,section,script=data["css"],data["section"],data["script"]

def upsert(src,start,end,block,anchor):
    if start in src and end in src:
        a=src.index(start); b=src.index(end,a)+len(end)
        return src[:a]+block+src[b:]
    if anchor not in src: raise SystemExit(f"missing anchor for {start}")
    return src.replace(anchor,block+"\n"+anchor,1)

nav='  <button role="tab" aria-selected="false" data-section="companions">Companions</button>\n'
